package localchat;
import java.nio.file.*;import java.util.*;import javax.swing.*;
public final class HotfolderReuseTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");Path project=Files.createDirectories(home.resolve("sources/506556")),other=Files.createDirectories(home.resolve("other-factory/506556"));Path chats=Files.createDirectories(home.resolve("app/conversatii"));
  var original=new Conversations.State();original.contextMode="mbs";original.toolsEnabled=true;original.title="My original project title";original.projectStatus="completed";original.archived=true;original.draft="My unsent custom question";original.model="original-model";original.bookmarks.add(0);
  Path file=Conversations.newFile(chats);List<ChatClient.Message> history=List.of(ChatClient.Message.user("Continua proiectul 506556"),ChatClient.Message.assistant("Confirmed historical findings",List.of(),"fixture"));Conversations.save(file,project.toString(),history,original);
  var alternate=new Conversations.State();alternate.contextMode="mbs";alternate.toolsEnabled=true;alternate.hotfolderProject=other.toString();alternate.title="Same number, different source";Path alternateFile=Conversations.newFile(chats);Conversations.save(alternateFile,other.toString(),history,alternate);
  Files.writeString(project.resolve("old.msg"),"old");var watcher=new Hotfolder(home.resolve("single-project-watcher.json"),0);check(watcher.scan(project,0).isEmpty(),"selected project folder is inventoried without inference");Files.writeString(project.resolve("added.eml"),"new");watcher.scan(project,1);var detected=watcher.scan(project,2);check(detected.size()==1&&detected.get(0).folder().toRealPath().equals(project.toRealPath())&&detected.get(0).files().contains("added.eml"),"new email detected when working folder is the project itself");
  var change=new Hotfolder.Change("506556",project,false,List.of("incoming.msg"),"first");check(HotfolderChats.find(Conversations.list(chats),change).file().equals(file),"exact source folder wins over same project number elsewhere");
  for(String lang:I18n.CODES){I18n.setLanguage(lang);check(Hotfolder.prompt(change).startsWith(I18n.text("Am adaugat un email nou in proiectul {0}.","506556")),"localized single email "+lang);var many=new Hotfolder.Change("506556",project,false,List.of("a.eml","b.MSG","other.pdf"),"many");check(Hotfolder.prompt(many).startsWith(I18n.text("Am adaugat emailuri noi in proiectul {0}.","506556")),"mixed files retain plural email introduction "+lang);}I18n.setLanguage("ro");
  LocalChat[] app={null};try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("Not called",1,1)))){
   FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("app"),server.url());AttachmentTest.input(app[0]).setText("Unrelated active draft");FeatureTest.call(app[0],"createHotfolderDraft",new Class<?>[]{Hotfolder.Change.class},change);var saved=Conversations.load(file);check(Conversations.list(chats).size()==2,"no third conversation created for processed or archived project");check(saved.messages().size()==2&&saved.messages().get(1).content.equals("Confirmed historical findings")&&saved.state().bookmarks.contains(0),"history and bookmark preserved");check(saved.state().title.equals(original.title)&&saved.state().model.equals(original.model),"original title and model preserved");check(!saved.state().archived&&saved.state().unread&&saved.state().projectStatus.equals("restarted"),"new email reopens existing archived project and notifies");check(saved.state().draft.startsWith(original.draft)&&saved.state().draft.contains("incoming.msg"),"custom draft preserved alongside new email preparation");check(AttachmentTest.input(app[0]).getText().equals("Unrelated active draft")&&server.requests.isEmpty(),"background update does not switch current chat or infer");FeatureTest.call(app[0],"openSession",new Class<?>[]{Conversations.Saved.class},saved);AttachmentTest.input(app[0]).setText("Live pending question");FeatureTest.call(app[0],"setBusy",new Class<?>[]{boolean.class},true);
    var next=new Hotfolder.Change("506556",project,false,List.of("next.eml"),"second");FeatureTest.call(app[0],"createHotfolderDraft",new Class<?>[]{Hotfolder.Change.class},next);FeatureTest.call(app[0],"createHotfolderDraft",new Class<?>[]{Hotfolder.Change.class},next);check(Conversations.list(chats).size()==2&&AttachmentTest.input(app[0]).getText().equals("Live pending question"),"busy same chat reused without disturbing active input");var state=AttachmentTest.state(app[0]);check(state.hotfolderPendingDraft.contains("next.eml")&&state.hotfolderPendingDraft.indexOf("next.eml")==state.hotfolderPendingDraft.lastIndexOf("next.eml"),"one deferred preparation per event");check(Conversations.load(file).state().hotfolderPendingDraft.contains("next.eml"),"pending update survives restart");FeatureTest.call(app[0],"setBusy",new Class<?>[]{boolean.class},false);FeatureTest.call(app[0],"openSession",new Class<?>[]{Conversations.Saved.class},Conversations.load(file));check(AttachmentTest.input(app[0]).getText().startsWith("Live pending question")&&AttachmentTest.input(app[0]).getText().contains("next.eml"),"explicit reopen presents deferred update and retains user's draft");check(state.hotfolderPendingDraft.isEmpty()&&!state.unread&&server.requests.isEmpty(),"opening is not sending and clears pending notification");app[0].dispose();});
  }finally{FeatureTest.edt(()->{for(var window:java.awt.Window.getWindows())window.dispose();});}
  System.out.println("PASS: "+checks+" hotfolder reuse/email-type checks; no external API or production writes");System.exit(0);
 }
}
